#include "shell/Shaders.h"

#include <cstddef>
#include <cstdint>

// Headers generated by bgfx_compile_shaders (src/shell/CMakeLists.txt), one per shader profile:
// Direct3D 12 (DXIL, with JPOG_DXC), Direct3D 11 (DXBC), Vulkan (SPIR-V) and OpenGL (GLSL 4.30)
// on Windows; Vulkan and OpenGL on Linux; Metal on macOS.
#if defined(_WIN32)
#include "dxbc/fs_imgui.sc.bin.h"
#include "dxbc/vs_imgui.sc.bin.h"
#endif
#if defined(JPOG_SHADERS_DXIL)
#include "dxil/fs_imgui.sc.bin.h"
#include "dxil/vs_imgui.sc.bin.h"
#endif
#if defined(_WIN32) || (defined(__linux__) && !defined(__ANDROID__))
#include "glsl/fs_imgui.sc.bin.h"
#include "glsl/vs_imgui.sc.bin.h"
#include "spirv/fs_imgui.sc.bin.h"
#include "spirv/vs_imgui.sc.bin.h"
#endif
#if defined(__APPLE__)
#include "metal/fs_imgui.sc.bin.h"
#include "metal/vs_imgui.sc.bin.h"
#endif

namespace jpog::shell
{

namespace
{

struct Blob
{
	const std::uint8_t* data = nullptr;
	std::uint32_t size = 0;
};

template <std::size_t N> Blob MakeBlob(const std::uint8_t (&data)[N])
{
	return {data, static_cast<std::uint32_t>(N)};
}

struct ProgramBlobs
{
	Blob vertex;
	Blob fragment;
};

ProgramBlobs FindBlobs(ShaderProgram program, bgfx::RendererType::Enum renderer)
{
	(void)program; // only ImGui for now
	switch (renderer)
	{
#if defined(_WIN32)
#if defined(JPOG_SHADERS_DXIL)
	case bgfx::RendererType::Direct3D12:
		return {MakeBlob(vs_imgui_dxil), MakeBlob(fs_imgui_dxil)};
#else
	case bgfx::RendererType::Direct3D12: // without DXIL, Direct3D 12 loads DXBC (Shader Model 5)
#endif
	case bgfx::RendererType::Direct3D11:
		return {MakeBlob(vs_imgui_dxbc), MakeBlob(fs_imgui_dxbc)};
#endif
#if defined(_WIN32) || (defined(__linux__) && !defined(__ANDROID__))
	case bgfx::RendererType::Vulkan:
		return {MakeBlob(vs_imgui_spv), MakeBlob(fs_imgui_spv)};
	case bgfx::RendererType::OpenGL:
		return {MakeBlob(vs_imgui_glsl), MakeBlob(fs_imgui_glsl)};
#endif
#if defined(__APPLE__)
	case bgfx::RendererType::Metal:
		return {MakeBlob(vs_imgui_mtl), MakeBlob(fs_imgui_mtl)};
#endif
	default:
		return {};
	}
}

} // namespace

bgfx::ProgramHandle CreateProgram(ShaderProgram program)
{
	const ProgramBlobs blobs = FindBlobs(program, bgfx::getRendererType());
	if (blobs.vertex.data == nullptr)
		return BGFX_INVALID_HANDLE;
	const bgfx::ShaderHandle vertex = bgfx::createShader(bgfx::makeRef(blobs.vertex.data, blobs.vertex.size));
	const bgfx::ShaderHandle fragment = bgfx::createShader(bgfx::makeRef(blobs.fragment.data, blobs.fragment.size));
	return bgfx::createProgram(vertex, fragment, true);
}

} // namespace jpog::shell
